'use strict';
// Sprites: every character is our own — concepts drawn with Meshy (Pro plan, outputs owned),
// animated with Wan 2.2 (Apache 2.0), sliced and toned by tools/. No third-party sprite packs.
// Each character's strips live in assets/sliced/<type>/ and are baked by tools/bake-from-sheet.py.
// GENERATED — do not edit by hand, re-bake.

const Sprites = (() => {
  const FRAME = 96, FEET = 81; // the feet anchor row within a frame
  const DATA = {
    drone: {
      fly: { frames: 16, w: 192, src: 'data:image/png;base64,' },
    },
    hero: {
      idle: { frames: 16, w: 192, src: 'data:image/png;base64,' },
      attack: { frames: 9, w: 192, src: 'data:image/png;base64,' },
      hurt: { frames: 16, w: 192, src: 'data:image/png;base64,' },
      run: { frames: 11, w: 192, src: 'data:image/png;base64,' },
      death: { frames: 18, w: 192, src: 'data:image/png;base64,' },
    },
    punk: {
      idle: { frames: 16, w: 192, src: 'data:image/png;base64,' },
      run: { frames: 11, w: 192, src: 'data:image/png;base64,' },
      hurt: { frames: 17, w: 192, src: 'data:image/png;base64,' },
    },
    shield: {
      idle: { frames: 16, w: 192, src: 'data:image/png;base64,' },
      run: { frames: 12, w: 192, src: 'data:image/png;base64,' },
      hurt: { frames: 17, w: 192, src: 'data:image/png;base64,' },
    },
    thrower: {
      idle: { frames: 16, w: 192, src: 'data:image/png;base64,' },
      run: { frames: 9, w: 192, src: 'data:image/png;base64,' },
      hurt: { frames: 16, w: 192, src: 'data:image/png;base64,' },
    },
    fencer: {
      idle: { frames: 16, w: 192, src: 'data:image/png;base64,' },
      run: { frames: 12, w: 192, src: 'data:image/png;base64,' },
      hurt: { frames: 29, w: 192, src: 'data:image/png;base64,' },
      guard: { frames: 16, w: 192, src: 'data:image/png;base64,' },
    },
    adapt: {
      idle: { frames: 16, w: 192, src: 'data:image/png;base64,' },
      run: { frames: 19, w: 192, src: 'data:image/png;base64,' },
      hurt: { frames: 16, w: 192, src: 'data:image/png;base64,' },
    },
    twin: {
      idle: { frames: 16, w: 192, src: 'data:image/png;base64,' },
      run: { frames: 13, w: 192, src: 'data:image/png;base64,' },
      hurt: { frames: 16, w: 192, src: 'data:image/png;base64,' },
    },
    boss: {
      idle: { frames: 16, w: 192, src: 'data:image/png;base64,' },
      run: { frames: 13, w: 192, src: 'data:image/png;base64,' },
      hurt: { frames: 17, w: 192, src: 'data:image/png;base64,' },
    },
    boss_beta: {
      idle: { frames: 16, w: 192, src: 'data:image/png;base64,' },
      run: { frames: 22, w: 192, src: 'data:image/png;base64,' },
      hurt: { frames: 16, w: 192, src: 'data:image/png;base64,' },
    },
    boss_maglev: {
      idle: { frames: 16, w: 192, src: 'data:image/png;base64,' },
      run: { frames: 12, w: 192, src: 'data:image/png;base64,' },
      hurt: { frames: 16, w: 192, src: 'data:image/png;base64,' },
    },
    boss_oni: {
      idle: { frames: 16, w: 192, src: 'data:image/png;base64,' },
      run: { frames: 26, w: 192, src: 'data:image/png;base64,' },
      hurt: { frames: 17, w: 192, src: 'data:image/png;base64,' },
    },
    boss_armorer: {
      idle: { frames: 16, w: 192, src: 'data:image/png;base64,' },
      run: { frames: 18, w: 192, src: 'data:image/png;base64,' },
      hurt: { frames: 16, w: 192, src: 'data:image/png;base64,' },
    },
    boss_double: {
      idle: { frames: 16, w: 192, src: 'data:image/png;base64,' },
      run: { frames: 15, w: 192, src: 'data:image/png;base64,' },
      hurt: { frames: 16, w: 192, src: 'data:image/png;base64,' },
    },
  };
  let loadedCount = 0, total = 0;
  for (const t in DATA) {
    for (const k in DATA[t]) {
      total++;
      const img = new Image();
      img.onload = () => loadedCount++;
      img.src = DATA[t][k].src;
      DATA[t][k].img = img;
    }
  }

  // Pre-scaled strips for the DENSE sheets, one entry per animation per size.
  //
  // The whole sprite path rests on a whole-number scale (see SPR in scene.js): a
  // source pixel then lands on screen as an exact N-by-N block whatever
  // fractional x the figure stands on. A dense sheet quietly broke that. Its
  // cell is 192 where the slot is 96, so its effective factor is scale/2 — half
  // of everyone else's, and whole only when the scale is even. At scale 3 it is
  // 1.5: nearest-neighbour then doubles every second row, and WHICH rows it
  // doubles moves with the figure, so the silhouette boils frame to frame. Below
  // 1 — a stepped-down quality ladder — it drops rows outright and thin details
  // (the blade, the scarf's edge) blink.
  //
  // So resize once, into a strip whose cell IS the destination size, and blit
  // that 1:1 from then on. Whole factors keep the nearest-neighbour edge; the
  // fractional ones take a smooth resize, which is soft but STILL, and still
  // beats a figure that shimmers. Only dense sheets go through here: at a whole
  // factor the direct path is already exact, and caching every enemy at every
  // size would cost tens of megabytes to fix nothing.
  // One cell size at a time: a dense sheet is only ever drawn at the hero's own
  // scale, so the size changes on a resize and not within a frame. Two sizes
  // alternating frame to frame would rebuild the strips twice a frame.
  const strips = new Map();
  let devK = 1; // backing-store pixels per CSS pixel of the main canvas (see draw)
  const setDeviceScale = k => { devK = k > 0 ? k : 1; };
  let stripCell = 0;
  function prescaled(type, anim, d, cell, src) {
    if (cell !== stripCell) { strips.clear(); stripCell = cell; }
    const key = type + '/' + anim;
    let cv = strips.get(key);
    if (cv) return cv;
    cv = document.createElement('canvas');
    cv.width = cell * d.frames;
    cv.height = cell;
    const c = cv.getContext('2d');
    c.imageSmoothingEnabled = cell % d.w !== 0;
    c.imageSmoothingQuality = 'high';
    c.drawImage(src || d.img, 0, 0, d.w * d.frames, d.w, 0, 0, cell * d.frames, cell);
    strips.set(key, cv);
    return cv;
  }

  // ---------- Blade retint (cosmetic palettes) ----------
  // The hero's steel and swing trails wear exactly the V2 'ice trail' family —
  // five tones no other part of the figure carries (the visor keeps its own
  // cyan; its two white glint pixels share the family and tint along, which
  // reads as the visor catching the blade's light). A bought palette remaps
  // that family onto its own five-step ramp once, into an offscreen canvas;
  // retint(null) restores the shipped sheets. Enemies never retint.
  const ICE = [[0xea, 0xfc, 0xff], [0xbf, 0xef, 0xff], [0x6e, 0xd6, 0xff],
               [0x57, 0xb8, 0xe8], [0x3d, 0x84, 0xb8]];
  let tintRamp = null; // five [r,g,b] targets aligned with ICE, or null
  function retint(coreHex) {
    if (!coreHex) tintRamp = null;
    else {
      const c = [1, 3, 5].map(i => parseInt(coreHex.slice(i, i + 2), 16));
      const mx = (a, b, k) => [0, 1, 2].map(i => Math.round(a[i] + (b[i] - a[i]) * k));
      const W = [255, 255, 255], B = [0, 0, 0];
      // the same bright-to-deep ladder the source tones walk
      tintRamp = [mx(c, W, 0.72), mx(c, W, 0.45), mx(c, W, 0.15), c, mx(c, B, 0.25)];
    }
    for (const k in DATA.hero) { delete DATA.hero[k].cv; delete DATA.hero[k].cvRamp; }
    strips.clear();
    stripCell = 0; // prescaled strips were cut from the old colors
  }
  // The recolored sheet for one animation, built lazily and cached until the
  // palette changes. data: URIs are same-origin, so getImageData is allowed.
  function tinted(d) {
    if (d.cv && d.cvRamp === tintRamp) return d.cv;
    const cv = document.createElement('canvas');
    cv.width = d.img.naturalWidth;
    cv.height = d.img.naturalHeight;
    const c = cv.getContext('2d');
    c.drawImage(d.img, 0, 0);
    const im = c.getImageData(0, 0, cv.width, cv.height);
    const p = im.data;
    for (let i = 0; i < p.length; i += 4) {
      if (!p[i + 3]) continue;
      for (let j = 0; j < 5; j++) {
        const s = ICE[j];
        if (p[i] === s[0] && p[i + 1] === s[1] && p[i + 2] === s[2]) {
          const t = tintRamp[j];
          p[i] = t[0]; p[i + 1] = t[1]; p[i + 2] = t[2];
          break;
        }
      }
    }
    c.putImageData(im, 0, 0);
    d.cv = cv;
    d.cvRamp = tintRamp;
    return cv;
  }

  // ---------- Scene light on the figures ----------
  // The figures were rendered on a flat key, under even light; the world is lit
  // by neon, signs and wet asphalt. Two cheap terms tie them into the act:
  //   rim    — the top and side edges of the silhouette catch the act's sign
  //            colour (the hat, the shoulders, the outline of a blade arm);
  //   bounce — the feet and shins pick up the floor's colour, fading out by the
  //            waist, the other half of the wet-ground reflection.
  // Both come from the alpha alone, so one mask per animation per act, built at
  // half resolution (the light is soft — a quarter of the memory) and added on
  // top of the sprite with 'lighter'. Weapons and accents keep their own
  // colours: this only lights what is already there.
  let light = null;        // { rim: [r,g,b], bounce: [r,g,b], key } or null
  const RIM_A = 0.22, BOUNCE_A = 0.15;
  // the hero carries his own cyan halo and has to read first — half the scene light
  const LIGHT_K = { hero: 0.5 };
  function setLight(l) {
    light = l ? { rim: hexRGB(l.rim), bounce: hexRGB(l.bounce), key: l.rim + l.bounce } : null;
  }
  const hexRGB = h => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16));
  function lightStrip(type, d) {
    if (d.lit && d.litKey === light.key) return d.lit;
    const fw = d.w || FRAME, hw = fw >> 1, n = d.frames;
    // the pixels are read on a CPU-side scratch canvas: reading back a GPU canvas
    // waits for the whole pipeline, and a burst of these at an act's first frame
    // froze the game for seconds
    const scratch = document.createElement('canvas');
    scratch.width = hw * n; scratch.height = hw;
    const sx = scratch.getContext('2d', { willReadFrequently: true });
    sx.imageSmoothingEnabled = true;
    sx.imageSmoothingQuality = 'high';
    sx.drawImage(d.img, 0, 0, fw * n, fw, 0, 0, hw * n, hw);
    const im = sx.getImageData(0, 0, scratch.width, scratch.height);
    const cv = document.createElement('canvas');
    cv.width = hw * n; cv.height = hw;
    const c = cv.getContext('2d');
    const p = im.data, W = cv.width, H = hw;
    const A = new Float32Array(W * H);
    for (let i = 0; i < W * H; i++) A[i] = p[i * 4 + 3] / 255;
    const feet = Math.round(FEET / FRAME * hw);          // the feet row in the half cell
    const span = Math.round(hw * 0.17);                  // bounce fades out over this height
    const noBounce = type === 'drone';                   // a hovering hull has no floor under it
    const [rr, rg, rb] = light.rim, [br, bg, bb] = light.bounce;
    for (let y = 0; y < H; y++) {
      const bw = noBounce ? 0 : Math.max(0, 1 - (feet - y) / span) * (y <= feet + 2 ? 1 : 0);
      for (let x = 0; x < W; x++) {
        const i = y * W + x, a = A[i];
        let o = i * 4;
        if (a < 0.05) { p[o + 3] = 0; continue; }
        const up = y >= 2 ? A[i - 2 * W] : 0;
        const lf = x % hw ? A[i - 1] : 0, rt = (x + 1) % hw ? A[i + 1] : 0;
        const rim = Math.min(1, Math.max(0, a - up, 0.6 * (a - Math.min(lf, rt))));
        const ri = rim * RIM_A, bi = bw * BOUNCE_A * a;
        const tot = ri + bi;
        if (tot < 0.01) { p[o + 3] = 0; continue; }
        p[o] = (rr * ri + br * bi) / tot;
        p[o + 1] = (rg * ri + bg * bi) / tot;
        p[o + 2] = (rb * ri + bb * bi) / tot;
        p[o + 3] = Math.min(255, tot * 255);
      }
    }
    c.putImageData(im, 0, 0);
    d.lit = cv; d.litKey = light.key;
    return cv;
  }

  // A sprite frame: (x, feetY) — the feet point, face ±1 — look direction,
  // glow — neon halo color (a canvas shadow around opaque pixels).
  function draw(c2d, type, anim, idx, x, feetY, scale, face, glow) {
    const t = DATA[type];
    const d = t && t[anim];
    if (!d || !d.img.complete || !d.img.naturalWidth) return false;
    const src = type === 'hero' && tintRamp ? tinted(d) : d.img;
    const f = ((idx % d.frames) + d.frames) % d.frames;
    c2d.save();
    c2d.imageSmoothingEnabled = false;
    c2d.translate(x, feetY);
    c2d.scale(face || 1, 1);
    if (glow) { c2d.shadowColor = glow; c2d.shadowBlur = 12; }
    // An animation may be stored denser than the roster (the hero is: a
    // 192px cell for a 96px slot). The SOURCE rect follows the cell, the
    // destination stays on the game's own FRAME/FEET — so density changes
    // detail and nothing else: same size, same ground, same anchor.
    const fw = d.w || FRAME;
    const dest = FRAME * scale;
    const dx = -FRAME / 2 * scale, dy = -FEET * scale;
    // How many source pixels one DEVICE pixel gets. The canvas carries its own
    // scale (DPR, the resolution ladder), so the factor that decides whether the
    // resample is clean is the one measured after it, not the one we passed in.
    // It is the STABLE device scale (setDeviceScale, from resize), not the live
    // transform: the hit's punch-zoom and a tumbling corpse change the transform
    // every frame, and each new value used to wipe and rebuild every cached
    // strip — 30 landed hits rebuilt ~1000 strips and the frame rate fell to 30.
    // Under a transient zoom the cached strip is simply drawn a touch larger.
    const k = devK;
    const ratio = dest * k / fw;
    if (fw > FRAME && Math.abs(ratio - Math.round(ratio)) > 1e-3) {
      // The cell is a whole number of pixels, so the destination has to be a
      // whole number of DEVICE pixels too, or the blit is 126.72-from-127 and
      // resamples all over again — which measured worse than the bug it was
      // fixing. Sizing back through k makes it exactly 1:1; `s` carries the
      // sub-pixel difference into the anchor so the boots do not drift.
      const cell = Math.max(1, Math.round(dest * k));
      const size = cell / k, s = size / dest;
      c2d.drawImage(prescaled(type, anim, d, cell, src), f * cell, 0, cell, cell,
        dx * s, dy * s, size, size);
    } else {
      c2d.drawImage(src, f * fw, 0, fw, fw, dx, dy, dest, dest);
    }
    if (light) {
      const lit = lightStrip(type, d), hw = (d.w || FRAME) >> 1;
      c2d.shadowBlur = 0;
      c2d.shadowColor = 'transparent';
      c2d.imageSmoothingEnabled = true;
      c2d.globalCompositeOperation = 'lighter';
      if (LIGHT_K[type]) c2d.globalAlpha *= LIGHT_K[type];
      c2d.drawImage(lit, f * hw, 0, hw, hw, dx, dy, dest, dest);
    }
    c2d.restore();
    return true;
  }

  // How many frames a sheet actually holds. The callers time animations by
  // duration and divide by this, so a re-bake that changes the count changes
  // nothing else — see the hero's frame picker in scene.js.
  const frames = (type, anim) => {
    const d = DATA[type] && DATA[type][anim];
    return (d && d.frames) || 1;
  };

  return { draw, frames, retint, setLight, setDeviceScale, FRAME, FEET, ready: () => loadedCount === total };
})();
